
const original='A browser should make reading comfortable. Find a word, move to the next match, or change the text size. This browser preview keeps the search controls above the page. Page zoom changes the whole layout; text size changes reading type. Find browser on this page to try all three matches.';let current=0,marks=[];const box=document.getElementById('sample');function search(){const q=document.getElementById('query').value;box.replaceChildren();marks=[];current=0;if(!q){box.textContent=original;document.getElementById('matches').textContent='0 matches';return}let at=0,pos;while((pos=original.toLowerCase().indexOf(q.toLowerCase(),at))>=0){box.append(document.createTextNode(original.slice(at,pos)));const m=document.createElement('mark');m.textContent=original.slice(pos,pos+q.length);box.append(m);marks.push(m);at=pos+q.length}box.append(document.createTextNode(original.slice(at)));select();r2.request('page.find',{query:q,caseSensitive:false,navigationId:'demo'},()=>({count:marks.length,index:0})).catch(e=>r2.toast(e.message))}function select(){marks.forEach((m,i)=>{m.style.outline=i===current?'3px solid #245b9b':'none';m.setAttribute('aria-current',String(i===current))});document.getElementById('matches').textContent=marks.length?(current+1)+' of '+marks.length:'0 matches';marks[current]?.scrollIntoView({block:'nearest'})}document.getElementById('query').oninput=search;document.getElementById('next').onclick=()=>{if(marks.length)current=(current+1)%marks.length;select();r2.request('page.find.next',{direction:1,navigationId:'demo'},()=>true)};document.getElementById('previous').onclick=()=>{if(marks.length)current=(current+marks.length-1)%marks.length;select();r2.request('page.find.next',{direction:-1,navigationId:'demo'},()=>true)};function resize(){const zoom=+document.getElementById('zoom').value/100,text=+document.getElementById('text').value/100;box.style.fontSize=(Math.max(22,24*zoom*text)*(innerWidth>=3000?2:1))+'px';box.style.padding=(32*zoom)+'px';r2.request('page.scale',{zoom,text,navigationId:'demo'},()=>true).catch(e=>r2.toast(e.message))}document.getElementById('zoom').onchange=document.getElementById('text').onchange=resize;search();